        # Fall back to inspecting annotations directly
        sig = inspect.signature(stop_after_attempt.__call__)
        for name, param in sig.parameters.items():
            if param.annotation is not inspect.Parameter.empty:
                hints[name] = param.annotation

    # The annotation for retry_state should reference RetryCallState, not be an empty string
    retry_state_annotation = hints.get('retry_state', '')
    # It should not be an empty string
